            if (commandResource.UpdateScheduledTaskOption.IsSet)
                writer.WriteBoolean("updateScheduledTask", commandResource.UpdateScheduledTaskOption.Value!.Value);

            if (commandResource.LastExecutionTimeOption.IsSet)
                if (commandResource.LastExecutionTimeOption.Value != null)
                    writer.WriteString("lastExecutionTime", commandResource.LastExecutionTimeOption.Value!.Value.ToString(LastExecutionTimeFormat));
                else
                    writer.WriteNull("lastExecutionTime");
        }
    }
}
